import{loadHumanSprites,humanChoice,chooseHuman,humanMarkup,paintHumans,currentOutfit,wearItem,saveLook,loadLook,savedLooks,humanSnapshot}from'./human-sprites.js?v=5';
import{ITEMS,SLOT_LABELS}from'./wardrobe.js?v=5';
import{patchSvg}from'./dom-render.js?v=5';
import{createRoom}from'./room.js?v=5';
import{createAnimalVisitors}from'./animal-visitors.js?v=6';
import{KEY,FURNITURE,SEEDS,CLOSET,LABELS,fresh,restore,apply,growth,validCell,passable,route,approach}from'./core.js?v=1';
import{avatar}from'./avatar.js?v=1';
import{rigAvatar,loadArt,artUrl}from'./rig.js?v=3';
// Cut-out rig with drop-in artwork (docs/pogeun-art-spec.md); vector parts until art/manifest.json exists.
await loadArt('art/manifest.json');
await loadHumanSprites();
const rigView=()=>pose==='sit'||pose==='walk'&&!back||pose==='water'||pose==='plant'?(back&&pose==='walk'?'back':'side'):back?'back':'front';
const person=(o,opts={})=>rigAvatar(o,{anim:opts.pose||'idle',time:opts.time||0,view:opts.view||'front',flip:opts.flip||false,height:opts.height||112,uid:opts.id||'rig'});
const $=id=>document.getElementById(id);let state=fresh(),storage=true;try{state=restore(localStorage.getItem(KEY));}catch{storage=false;}let mode='walk',selected=null,placing=null,moving=false,zoom=1,seq=0,pending=null,steps=[],stepIndex=0,actorCell=[...state.avatar],from=null,to=null,started=0,pose='idle',face=1,back=false,busy=false,slot='top',pointer=null,photoUrl=null,photoBusy=false,lastFrame=0,petCell=[6,7],petPath=[],petStep=0,petStart=0,petFrom=null,petTo=null,petWait=0,petSleeping=false;
const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
const P=(c,r)=>[480+(c-r)*42,220+(c+r)*22];
let actorPosition=P(...actorCell);
let fishCount=0;try{fishCount=Math.max(0,Number(localStorage.getItem('pogeun-fish-v1'))||0);}catch{}
const room=createRoom({world:$('world'),announce:say,onChange:()=>{render();$('walk-label').textContent=room.inside?'방바닥을 눌러 걸어가요':'잔디를 누르면 그곳으로 걸어가요';}});
const visitors=createAnimalVisitors({project:P,findRoute:route,getState:()=>state,redraw:render,announce:say,world:$('world'),reduced,onFish:()=>{fishCount++;try{localStorage.setItem('pogeun-fish-v1',fishCount);}catch{}}});
const B={house:[0,0,418,416],bench:[428,80,355,322],daisy:[825,42,354,340],tulip:[1200,42,334,340],lavender:[0,401,380,324],pot:[425,460,307,257],pond:[773,445,415,280],tree:[1180,391,354,332],table:[18,720,363,300],bowl:[428,755,337,245],cushion:[779,741,420,267],lamp:[1270,716,191,305]};
function sprite(name,w,h){const own=artUrl('props',name);if(own)return`<image href="${own}" x="${-w/2}" y="${-h+8}" width="${w}" height="${h}" preserveAspectRatio="xMidYMax meet" pointer-events="none"/>`;const b=B[name],id='art'+(++seq);return`<svg x="${-w/2}" y="${-h+8}" width="${w}" height="${h}" viewBox="${b.join(' ')}" preserveAspectRatio="xMidYMax meet" aria-hidden="true" pointer-events="none"><defs><clipPath id="${id}"><rect x="${b[0]}" y="${b[1]}" width="${b[2]}" height="${b[3]}"/></clipPath></defs><image href="../littlepark/garden-atlas.webp" width="1536" height="1024" clip-path="url(#${id})"/></svg>`;}
function itemArt(p){if((p.kind==='path'||p.kind==='fence')&&artUrl('props',p.kind))return sprite(p.kind,...(p.kind==='path'?[70,40]:[90,75]));if(p.kind==='path')return'<path d="M-29-4l18-13 32 7 10 14-26 14-31-8z" fill="#e5ddbc" stroke="#b6b997" stroke-width="2"/><path d="M-17-5l11-5 17 3" fill="none" stroke="#f6f0d8" stroke-width="3"/>';if(p.kind==='fence')return'<g stroke="#a4ac8a" stroke-width="2" fill="#e4dfbe"><path d="M-38-31l76-19v9l-76 19zM-38-10l76-19v9l-76 19z"/><path d="M-28-39v48M0-46v49M28-53v49" stroke="#dedcc0" stroke-width="8"/></g>';
 if(p.kind==='pot'&&p.seed){if(growth(p)>=1)return sprite(p.seed,69,89);return sprite('pot',53,51)+`<g transform="translate(0 -24) scale(${.4+.6*growth(p)})"><path d="M0 0v-32" stroke="#72965b" stroke-width="4"/><path d="M0-12Q-27-38-22-15Q-10-5 0-9M0-21Q24-44 22-22Q10-12 0-16" fill="#97b47a"/></g>`;}
 return sprite(p.kind,...({bench:[104,84],pot:[53,51],tree:[122,155],bowl:[44,34],pond:[119,79],table:[89,84],cushion:[79,58],lamp:[40,89]}[p.kind]));}
function kitten(){const b=petSleeping?[0,745,665,425]:[710,0,544,650],id='momo'+(++seq);return`<ellipse cy="5" rx="18" ry="6" fill="#63794b1a"/><svg x="-28" y="-49" width="56" height="56" viewBox="${b.join(' ')}" preserveAspectRatio="xMidYMax meet" aria-hidden="true" pointer-events="none"><defs><clipPath id="${id}"><rect x="${b[0]}" y="${b[1]}" width="${b[2]}" height="${b[3]}"/></clipPath></defs><image href="../littlepark/momo-atlas.webp" width="1254" height="1254" clip-path="url(#${id})"/></svg><ellipse class="object-hit" data-cat="1" cx="0" cy="-20" rx="24" ry="28" role="button" tabindex="0" aria-label="모모 만나기"/>`;}
function actor(phase=0){return (humanMarkup({pose,face,back,time:performance.now()/1000})||person(state.outfit,{pose,time:performance.now()/1000,view:rigView(),flip:face<0,id:'island-person'}))+'<ellipse class="object-hit" data-avatar="1" cy="-65" rx="29" ry="54" role="button" tabindex="0" aria-label="내 아바타 옷장 열기"/>';}
function render(){if(room.inside){room.render();context();return;}const night=state.theme==='sunset';$('game').dataset.theme=state.theme;$('scene').classList.toggle('decorating',mode==='decorate');const sea=night?['#ebdfcf','#b8d3d0']:['#d1efeb','#a8d8d4'];const cells=[];for(let r=0;r<9;r++)for(let c=0;c<9;c++)if(validCell(c,r)){const[x,y]=P(c,r);cells.push(`<path class="cell" data-cell="${c},${r}" role="button" tabindex="${mode==='decorate'?0:-1}" aria-label="잔디 ${c+1}열 ${r+1}행" d="M${x} ${y-22}l42 22-42 22-42-22z"/>`);}
 const objs=state.items.map(p=>({depth:p.c+p.r,html:(()=>{const[x,y]=P(p.c,p.r),size=p.kind==='tree'?120:p.kind==='lamp'?90:p.kind==='pot'?85:70;return`<g data-node-key="item-${p.id}" transform="translate(${x} ${y})" class="${selected===p.id?'selected':''}"><ellipse class="chosen-mark" rx="37" ry="19"/><g transform="scale(${p.rot?-1:1} 1)" class="${p.kind==='tree'?'leaf':''}">${itemArt(p)}</g><rect class="object-hit" data-id="${p.id}" x="-33" y="${-size+5}" width="66" height="${size+8}" rx="15" role="button" tabindex="0" aria-label="${FURNITURE[p.kind].name}${p.seed?' · '+SEEDS[p.seed]:''}"/>${p.kind==='lamp'&&night?'<ellipse cy="-30" rx="45" ry="40" fill="url(#glow)" pointer-events="none"/>':''}</g>`;})()}));
 const seat=pose==='sit'?state.items.find(p=>p.id===selected):null;const[ax,ay]=seat?P(seat.c,seat.r):actorPosition,[px,py]=P(...petCell);objs.push({depth:actorCell[0]+actorCell[1]+.15,html:`<g id="person" transform="translate(${ax} ${ay-(pose==='sit'?25:0)})">${actor()}</g>`},{depth:petCell[0]+petCell[1]+.1,html:`<g id="pet" transform="translate(${px} ${py})">${kitten()}</g>`});
 const visitor=visitors.render();if(visitor)objs.push(visitor);
 patchSvg($('world'),`<defs><linearGradient id="sea" x2="0" y2="1"><stop stop-color="${sea[0]}"/><stop offset="1" stop-color="${sea[1]}"/></linearGradient><linearGradient id="grass" x2=".5" y2="1"><stop stop-color="#c3d9a0"/><stop offset="1" stop-color="#adc98a"/></linearGradient><radialGradient id="glow"><stop stop-color="#fff0b5" stop-opacity=".6"/><stop offset="1" stop-color="#fff0b5" stop-opacity="0"/></radialGradient><filter id="blur"><feGaussianBlur stdDeviation="12"/></filter></defs><rect width="960" height="800" fill="url(#sea)"/><g fill="none" stroke="#f5fff3" stroke-width="3" opacity=".5" class="ocean-line"><path d="M30 265q45 14 89-1M769 180q36 10 73 0M812 595q45 13 90 0M40 596q30 12 73 0M323 735q60 13 120-1"/></g><g fill="#fffdf0" opacity=".6"><ellipse cx="190" cy="153" rx="54" ry="10"/><ellipse cx="211" cy="144" rx="24" ry="14"/><ellipse cx="750" cy="120" rx="43" ry="10"/></g><ellipse cx="480" cy="490" rx="355" ry="154" fill="#548e8524" filter="url(#blur)"/>
 <path d="M474 190C635 178 794 255 842 375C896 485 750 591 566 628C405 668 214 596 124 478C65 392 144 270 288 224C350 198 411 190 474 190Z" fill="#87c1ac" stroke="#e6f4d4" stroke-width="18"/><path d="M474 190C635 178 794 255 842 375C896 485 750 591 566 628C405 668 214 596 124 478C65 392 144 270 288 224C350 198 411 190 474 190Z" fill="#e9d9ae" stroke="#f2e7c9" stroke-width="7"/><path d="M474 223C619 210 749 282 792 382C835 476 704 560 551 594C407 627 250 564 174 464C120 391 187 294 306 256C360 236 420 225 474 223Z" fill="url(#grass)" stroke="#b5cc95" stroke-width="3"/>
 <g fill="#e4e9bb" opacity=".8">${[[230,400],[340,535],[650,525],[725,400],[402,553],[610,295],[255,460]].map(([x,y])=>`<path d="M${x} ${y}l-3-9 6 5 4-10 1 13"/>`).join('')}</g><g transform="translate(236 597) rotate(32)"><path d="M-28-18h66v143h-66z" fill="#ac8c61"/><path d="M-28-18h66v135h-66z" fill="#d0b481" stroke="#a98e66" stroke-width="2"/>${Array.from({length:8},(_,i)=>`<path d="M-27 ${i*16}h64" stroke="#ad9268" stroke-width="2"/>`).join('')}<path d="M-34-14v28M42-14v28M-34 97v28M42 97v28" stroke="#aa8f66" stroke-width="9"/><path d="M-34-14v24M42-14v24M-34 97v24M42 97v24" stroke="#c8b18a" stroke-width="5"/></g><g fill="#fff0d0" stroke="#d9c69e" stroke-width="1"><path d="M710 558q-10-16-23 0l12 9z"/><path d="M322 595q-10-16-23 0l12 9z"/></g><!-- painted island covers the vector island when provided --><image id="island-ground" href="art/world/island-cozy.webp" width="960" height="800" preserveAspectRatio="none" ${night?'style="filter:sepia(.18) saturate(.8)"':''}/>${visitors.seaMarkup()}<g id="cottage" transform="translate(480 345)"><image href="art/props/house-front.webp" x="-123" y="-216" width="246" height="225"/><rect data-house="1" x="-49" y="-94" width="98" height="107" rx="20" fill="transparent" role="button" tabindex="0" aria-label="우리 집 들어가기"/></g>${cells.join('')}${objs.sort((a,b)=>a.depth-b.depth).map(x=>x.html).join('')}<g id="effect"></g>`);paintHumans($('world'),{pose,face,back,time:performance.now()/1000});camera();context();shelf();$('home').classList.toggle('active',mode==='walk');$('decorate').classList.toggle('active',mode==='decorate');}
function camera(){const w=960/zoom,h=800/zoom;$('world').setAttribute('viewBox',`${480-w/2} ${400-h/2} ${w} ${h}`);}
function say(t){$('toast').textContent=t;}
function save(){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{storage=false;$('save-status').textContent='저장이 제한돼요. 이 창을 닫으면 진행이 사라질 수 있어요.';}}
function dispatch(e){const r=apply(state,e);if(!r.ok){say(r.why);return false;}state=r.state;save();return true;}
function context(){if(room.inside){$('context').innerHTML='<div class="text">나의 작은 집<small>폭신한 침대와 러그 · 방바닥을 눌러 걸어요</small></div><button data-act="leave-house">밖으로 나가기</button>';return;}const p=state.items.find(x=>x.id===selected);if(!p){$('context').innerHTML=`<div class="text">내가 꾸미는 작은 일상<small>${state.hearts?'모모와의 친밀도 '+state.hearts+' / 10':'화분을 눌러 첫 씨앗을 심어 보세요'} · 사과 ${state.apples}개</small></div><button data-act="closet">코디하기</button>`;return;}let b='';if(mode==='decorate')b=`<button data-act="move">옮기기</button><button class="secondary" data-act="rotate">돌리기</button>${p.seed?'':'<button class="secondary" data-act="store">보관</button>'}`;else if(p.kind==='pot')b=p.seed?`<button data-act="water">${growth(p)>=1?'꽃 기록하기':'물 주기'}</button>`:'<button data-act="seed">씨앗 심기</button>';else if(p.kind==='bench'||p.kind==='cushion')b='<button data-act="sit">앉아서 쉬기</button>';else if(p.kind==='tree')b='<button data-act="harvest">사과 따기</button>';else if(p.kind==='bowl')b='<button data-act="fill">물 채우기</button>';
 $('context').innerHTML=`<div class="text">${p.seed?SEEDS[p.seed]:FURNITURE[p.kind].name}<small>${moving?'옮길 빈 잔디 칸을 눌러 주세요':p.seed?growth(p)>=1?'활짝 피었어요. 시들지 않아요.':`자라는 중 ${Math.floor(growth(p)*100)}%`:mode==='decorate'?'자유롭게 배치하고 방향을 바꿔요':'가까이 걸어가서 함께해요'}</small></div><div class="buttons">${b}</div>`;}
function shelf(){const el=$('shelf'),scroll=el.scrollLeft;el.hidden=mode!=='decorate';if(mode==='decorate')el.innerHTML=Object.entries(FURNITURE).map(([kind,v])=>`<button class="item ${placing===kind?'active':''}" data-kind="${kind}"><svg viewBox="-75 -150 150 174" aria-hidden="true">${itemArt({kind})}</svg>${v.name}<small>${v.max-state.items.filter(p=>p.kind===kind).length}개 남음</small></button>`).join('');el.scrollLeft=scroll;}
function cancelWalk(){if(to||steps.length){dispatch({type:'walk',to:actorCell});}to=null;steps=[];pending=null;pose='idle';}
function walk(path,after=null){if(busy)return;if(!path.length){say('걸어갈 길이 막혀 있어요. 꾸미기에서 길을 비워 주세요.');return;}cancelWalk();steps=path;stepIndex=0;pending=after;pose='walk';if(path.length===1){finishWalk();return;}say('사뿐사뿐, 그쪽으로 가는 중이에요.');}
function finishWalk(){to=null;steps=[];pose='idle';dispatch({type:'walk',to:actorCell});const action=pending;pending=null;render();if(action)perform(action);}
function nearAction(type,id,seed){const p=state.items.find(x=>x.id===id);if(!p)return;walk(approach(state,actorCell,p),{type,id,seed});}
function perform(e){if(busy)return;busy=true;const target=state.items.find(p=>p.id===e.id);if(target){face=P(target.c,target.r)[0]<P(...actorCell)[0]?-1:1;back=target.c+target.r<actorCell[0]+actorCell[1];}pose=e.type==='water'||e.type==='fill'?'water':e.type==='plant'?'plant':e.type==='sit'?'sit':'idle';render();const[x,y]=P(...actorCell);if(['water','fill'].includes(e.type))$('effect').innerHTML=`<g transform="translate(${x+25} ${y-36})" class="waterdrop" fill="#83b7b9"><ellipse rx="3" ry="6"/><ellipse cx="12" cy="4" rx="3" ry="5"/><ellipse cx="22" cy="-3" rx="3" ry="5"/></g>`;setTimeout(()=>{const okay=dispatch(e);if(okay){say({water:'촉촉하게 물을 주었어요.',plant:'씨앗을 심었어요. 작은 잎이 고개를 내밀어요.',fill:'모모의 물그릇을 채웠어요.',harvest:'잘 익은 사과를 하나 땄어요.',sit:'잠깐, 파도 소리를 들으며 쉬어요.'}[e.type]||'');}if(!okay||e.type!=='sit')pose='idle';busy=false;render();},reduced?100:950);}
function modal(html){$('paper').innerHTML=html;if(!$('dialog').open)$('dialog').showModal();}
function closet(){cancelWalk();if(!ITEMS[slot])slot='top';const outfit=currentOutfit(),gender=humanChoice(),scroll=$('dialog').scrollTop;modal(`<small>MY WARDROBE · 모든 코디 무료</small><h2>오늘은 어떤 나?</h2><div class="looks"><button data-human="female" aria-pressed="${gender==='female'}" class="${gender==='female'?'chosen':''}">여자 캐릭터</button><button data-human="male" aria-pressed="${gender==='male'}" class="${gender==='male'?'chosen':''}">남자 캐릭터</button></div><div class="closet-stage"><img class="wardrobe-person" src="${humanSnapshot({preview:true})}" alt="${gender==='female'?'여자':'남자'} 캐릭터 현재 코디"><div class="caption">선택한 캐릭터 그대로, 옷만 갈아입어요</div></div><div class="closet-tabs">${Object.entries(SLOT_LABELS).map(([k,v])=>`<button data-slot="${k}" class="${slot===k?'active':''}">${v}</button>`).join('')}</div><div class="wardrobe">${ITEMS[slot].map(([v,label,color])=>`<button data-wear="${v}" class="${outfit[slot]===v?'selected':''}" aria-pressed="${outfit[slot]===v}"><span class="item-icon" data-item-icon="${v}"><img src="${humanSnapshot({preview:true,outfitOverride:{...outfit,[slot]:v}})}" alt="" loading="lazy"></span>${label}</button>`).join('')}</div><div class="looks">${savedLooks().map((_,i)=>`<button data-look="${i}">코디 ${i+1}</button>`).join('')}<button data-act="look-save">코디 저장</button></div><p class="closet-note">헤어는 다음 미용실 업데이트에서 만나요.</p><button class="primary" data-act="closet-done">이 모습으로 산책하기</button>`);$('dialog').scrollTop=scroll;}
function seeds(){modal(`<small>SEED POUCH</small><h2>처음 피울 꽃은?</h2><div class="seed-options">${Object.entries(SEEDS).map(([k,v])=>`<button data-seed="${k}"><svg viewBox="-45 -100 90 115">${sprite(k,70,95)}</svg>${v}</button>`).join('')}</div><p>꽃은 약 90초면 피어요.<br>물을 주면 조금 더 빨리 자라요.</p><small>자리를 비워도 자라고, 시들지 않아요.</small>`);}
function journal(){modal(`<small>ISLAND JOURNAL</small><h2>우리 섬의 작은 기록</h2>${[['dressed','내 모습으로 갈아입기'],['planted','첫 씨앗 심기'],['watered','꽃에 물 주기'],['filled','모모 물그릇 채우기'],['friend','모모와 인사하기'],['rested','벤치에 앉아 쉬기'],['decorated','가구를 내 자리에 놓기'],['harvested','사과 따기']].map(([k,v])=>`<div class="journal-row">${state.tasks[k]?'✓':'○'} ${v}</div>`).join('')}<p>모모와의 친밀도 ${state.hearts} / 10 · 사과 ${state.apples}개<br>바다 친구가 선물한 물고기 ${fishCount}마리</p>${Object.entries(SEEDS).map(([k,v])=>`<div class="journal-row">${v}<small>${state.items.filter(p=>p.seed===k&&growth(p)>=1).length}송이 개화 · ${state.items.filter(p=>p.seed===k&&growth(p)<1).length}개 성장 중</small></div>`).join('')}<small>포근섬 0.2 · 이 기기에 자동 저장<br>친구 방문·온라인 계정·구매 기능은 아직 없어요.</small>`);}
function help(){modal('<p><a href="sprite-playground/">동물 산책길 · 픽셀 캐릭터로 걷기 →</a></p><small>WELCOME TO YOUR ISLAND</small><h2>여기서는,<br>내 취향대로 살아가요.</h2><p>옷장에서 나를 꾸미고,<br>잔디를 눌러 섬을 산책해요.</p><p>집 문을 누르면 우리 집에 들어가요.<br>바다 친구가 준 물고기도 주워 보세요.</p><p>화분에 씨앗을 심고 물을 주거나<br>벤치에 앉아 잠깐 쉬어도 좋아요.</p><small>꾸미기에서는 가구를 놓고 옮길 수 있어요.<br>기본 의상과 가구는 모두 무료예요.</small><button class="primary" data-act="start">내 모습부터 골라볼래요</button><button class="primary" data-act="begin-walk">먼저 섬 둘러보기</button>');}
async function photograph(){if(photoBusy)return;photoBusy=true;say('우리 섬의 모습을 사진에 담고 있어요.');try{const clone=$('world').cloneNode(true);clone.setAttribute('xmlns','http://www.w3.org/2000/svg');clone.setAttribute('width','960');clone.setAttribute('height','800');clone.setAttribute('viewBox','0 0 960 800');for(const [i,fo] of [...clone.querySelectorAll('foreignObject')].entries()){const canvas=$('world').querySelectorAll('foreignObject canvas')[i];if(!canvas)continue;const im=document.createElementNS('http://www.w3.org/2000/svg','image');for(const a of ['x','y','width','height'])im.setAttribute(a,fo.getAttribute(a));im.setAttribute('href',canvas.toDataURL());fo.replaceWith(im);}clone.querySelectorAll('.cell,.object-hit,.chosen-mark').forEach(el=>el.remove());const cache=new Map();for(const image of clone.querySelectorAll('image')){const url=new URL(image.getAttribute('href'),location.href).href;if(!cache.has(url)){const blob=await(await fetch(url)).blob();const data=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(blob);});cache.set(url,data);}image.setAttribute('href',cache.get(url));}const svg=new Blob([new XMLSerializer().serializeToString(clone)],{type:'image/svg+xml'}),url=URL.createObjectURL(svg),img=new Image();try{img.src=url;await img.decode();const canvas=document.createElement('canvas');canvas.width=960;canvas.height=860;const c=canvas.getContext('2d');c.fillStyle='#fff9e9';c.fillRect(0,0,960,860);c.drawImage(img,0,0,960,800);c.fillStyle='#78876a';c.font='20px sans-serif';c.textAlign='center';c.fillText('MY LITTLE ISLAND · 포근섬',480,838);photoUrl=canvas.toDataURL('image/png');}finally{URL.revokeObjectURL(url);}modal(`<small>OUR ISLAND MEMORY</small><h2>오늘의 포근섬</h2><img class="photo" src="${photoUrl}" alt="지금 코디한 아바타와 꾸민 섬의 기념사진"><a class="primary download" href="${photoUrl}" download="my-little-island.png">사진 저장하기</a><p>코디와 배치를 바꾸면<br>사진에도 그대로 담겨요.</p>`);say('우리 섬의 오늘을 담았어요.');}catch{say('사진을 불러오지 못했어요. 잠시 뒤 다시 눌러 주세요.');}finally{photoBusy=false;}}
$('close').onclick=()=>$('dialog').close();$('closet').onclick=closet;$('journal').onclick=journal;$('help').onclick=help;$('camera').onclick=photograph;$('weather').onclick=()=>{dispatch({type:'theme',value:state.theme==='day'?'sunset':'day'});render();say(state.theme==='day'?'맑은 낮빛으로 바꿨어요.':'해 질 무렵의 바다예요.');};$('zoom-in').onclick=()=>{zoom=Math.min(1.45,zoom+.15);camera();};$('zoom-out').onclick=()=>{zoom=Math.max(1,zoom-.15);camera();};$('home').onclick=()=>{if(room.inside){room.leave();return;}mode='walk';selected=null;placing=null;moving=false;render();say('잔디를 누르면 그곳으로 걸어가요.');};$('decorate').onclick=()=>{if(room.inside){say('방에는 침대와 러그를 준비했어요. 방 꾸미기는 다음에 열려요.');return;}cancelWalk();mode='decorate';render();say('주머니에서 물건을 골라 빈 잔디 칸에 놓아요.');};
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.human){chooseHuman(b.dataset.human);render();closet();return;}if(b.dataset.slot){slot=b.dataset.slot;closet();}if(b.dataset.wear){wearItem(slot,b.dataset.wear);state.tasks.dressed=true;save();render();closet();}if(b.dataset.look!==undefined){loadLook(Number(b.dataset.look));render();closet();}if(b.dataset.kind){placing=b.dataset.kind;moving=false;selected=null;shelf();context();say(FURNITURE[placing].name+' · 빈 잔디 칸에 놓아 주세요.');}if(b.dataset.seed){$('dialog').close();nearAction('plant',selected,b.dataset.seed);}const act=b.dataset.act;if(act==='leave-house')room.leave();if(act==='closet')closet();if(act==='look-save'){saveLook();closet();}if(act==='closet-done'){$('dialog').close();mode='walk';render();say('새 코디로 산책을 시작해 볼까요?');}if(act==='start'){dispatch({type:'welcome'});closet();}if(act==='begin-walk'){dispatch({type:'welcome'});$('dialog').close();}if(act==='seed')seeds();if(['water','fill','sit','harvest'].includes(act))nearAction(act,selected);if(act==='move'){moving=true;placing=null;say('옮길 빈 잔디 칸을 눌러 주세요.');context();}if(act==='rotate'){if(dispatch({type:'rotate',id:selected}))render();}if(act==='store'){if(dispatch({type:'store',id:selected})){selected=null;render();say('주머니에 보관했어요. 다시 꺼낼 수 있어요.');}}});
function pick(target){if(busy)return;if(target.closest('[data-house]')){cancelWalk();room.enter();return;}if(target.closest('[data-fish]')){visitors.collectFish();return;}if(target.closest('[data-marine]')){say('바다 친구가 헤엄치고 있어요. 가끔 물고기를 선물해요.');return;}if(target.closest('[data-visitor]')){visitors.greet();return;}if(target.closest('[data-avatar]')){closet();return;}if(target.closest('[data-cat]')){const p={c:petCell[0],r:petCell[1]};const path=approach(state,actorCell,p);walk(path,{type:'pet'});return;}const item=target.closest('[data-id]');if(item){selected=Number(item.dataset.id);moving=false;placing=null;context();if(mode==='walk')say('아래에서 함께할 행동을 골라 주세요.');render();return;}const cell=target.closest('[data-cell]');if(!cell)return;const[c,r]=cell.dataset.cell.split(',').map(Number);if(mode==='decorate'){if(moving){if(dispatch({type:'move',id:selected,c,r})){moving=false;render();say('내가 고른 자리에 놓았어요.');}}else if(placing){if(dispatch({type:'place',kind:placing,c,r})){selected=state.next-1;render();say('섬에 새로운 자리가 생겼어요.');}}else say('물건을 먼저 골라 주세요.');}else walk(route(state,actorCell,[c,r]));}
$('world').addEventListener('pointerdown',e=>{pointer={x:e.clientX,y:e.clientY,id:Number(e.target.closest('[data-id]')?.dataset.id),target:e.target,moved:false};});$('world').addEventListener('pointermove',e=>{if(pointer&&Math.hypot(e.clientX-pointer.x,e.clientY-pointer.y)>12)pointer.moved=true;});$('world').addEventListener('pointerup',e=>{const p=pointer;pointer=null;if(p?.moved&&p.id&&mode==='decorate'){const pt=new DOMPoint(e.clientX,e.clientY).matrixTransform($('world').getScreenCTM().inverse());const c=Math.round(((pt.x-480)/42+(pt.y-220)/22)/2),r=Math.round(((pt.y-220)/22-(pt.x-480)/42)/2);selected=p.id;if(dispatch({type:'move',id:p.id,c,r})){render();say('새 자리에 놓았어요.');}return;}if(!p?.moved){if(room.inside){const pt=new DOMPoint(e.clientX,e.clientY).matrixTransform($('world').getScreenCTM().inverse());room.pick(e.target,pt.x,pt.y);}else pick(e.target);}});$('world').addEventListener('pointercancel',()=>pointer=null);$('world').addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();if(room.inside)room.pick(e.target,560,580);else pick(e.target);}});
function tick(t){if(room.inside){if(!$('dialog').open)room.tick(t);requestAnimationFrame(tick);return;}visitors.tick(t,busy||!!pointer||$('dialog').open||mode==='decorate');if(t-lastFrame>0&&!document.hidden&&!$('dialog').open){lastFrame=t;if(!steps.length&&!to&&!reduced){const el=$('person');if(el)paintHumans(el,{pose,face,back,time:t/1000});}if(steps.length){if(!to&&stepIndex<steps.length-1){from=[...actorPosition];to=P(...steps[++stepIndex]);started=t;const dc=steps[stepIndex][0]-actorCell[0],dr=steps[stepIndex][1]-actorCell[1];face=to[0]<from[0]?-1:1;back=dc<0||dr<0;}if(to){const a=reduced?1:Math.min(1,(t-started)/Math.max(16,Math.hypot(to[0]-from[0],to[1]-from[1])/110*1000)),x=from[0]+(to[0]-from[0])*a,y=from[1]+(to[1]-from[1])*a;actorPosition=[x,y];const el=$('person');if(el){el.setAttribute('transform',`translate(${x} ${y})`);paintHumans(el,{pose,face,back,time:t/1000});}if(a===1){actorCell=[...steps[stepIndex]];to=null;if(stepIndex===steps.length-1)finishWalk();}}}
 if(!busy&&!pointer&&t>petWait&&!reduced){if(!petTo){if(!petPath.length||petStep>=petPath.length-1){const targets=state.water?[[5,6],[4,6],[6,5]]:[[6,7],[7,6],[6,5]];const goal=targets[Math.floor(t/9000)%targets.length];petPath=route(state,petCell,goal);petStep=0;}if(petPath.length>1){petFrom=P(...petCell);petTo=P(...petPath[++petStep]);petStart=t;petSleeping=false;}}if(petTo){const a=Math.min(1,(t-petStart)/900),x=petFrom[0]+(petTo[0]-petFrom[0])*a,y=petFrom[1]+(petTo[1]-petFrom[1])*a,el=$('pet');if(el)el.setAttribute('transform',`translate(${x} ${y})`);if(a===1){petCell=[...petPath[petStep]];petTo=null;if(petStep===petPath.length-1){petWait=t+8000;petSleeping=state.hearts>1;if(el)el.innerHTML=kitten();}}}}
 }requestAnimationFrame(tick);}requestAnimationFrame(tick);
let stages='';setInterval(()=>{if(busy||pointer||steps.length||$('dialog').open)return;const x=state.items.filter(p=>p.seed).map(p=>growth(p)>=1?'flower':'leaf').join();if(stages!==x){stages=x;render();}else if(selected)context();},1800);
render();say('잔디를 눌러 걸어가거나, 옷장에서 나를 꾸며 보세요.');if(!state.welcomed)help();
